"""Isolated CLI-to-Bun representation acceptance; no consumer source changes."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import platform
import subprocess
import tempfile
import time

ROOT = Path('/home/massenhaft/workspaces/conpinion/dctx0ctl')
BINARY = ROOT / 'target/release/dctx0'
SPEC = '''workspace W {
 value Id = Int
 type Alias = Id
 type Status = Open | Closed
 type Maybe = Option<String>
 type Amount = Decimal
 type Packet { id: Id; status: Status; maybe: Maybe }
}
'''
NATIVE = '''import {strict as assert} from 'node:assert';
import {encode,decode} from './app/.dctx0/testing/typescript/wire-codecs.ts';
const started=performance.now();
const cases:string[]=[];
function check(name:string,body:()=>void){body();cases.push(name);}
check('global tagged enum encoding',()=>assert.deepEqual(encode('W.Status',{kind:'Open',payload:null}),{kind:'variant',value:{declaration:'W.Status',name:'Open',payload:null}}));
check('global tagged enum decoding',()=>assert.deepEqual(decode('W.Status',{kind:'variant',value:{declaration:'W.Status',name:'Closed',payload:null}}),{kind:'Closed',payload:null}));
check('undefined absence',()=>assert.equal(decode('W.Maybe',{kind:'option',value:null}),undefined));
check('record conversion',()=>assert.deepEqual(encode('W.Packet',{id:3,status:{kind:'Open',payload:null},maybe:undefined}),{kind:'record',value:{id:{kind:'integer',value:'3'},status:{kind:'variant',value:{declaration:'W.Status',name:'Open',payload:null}},maybe:{kind:'option',value:null}}}));
check('outer alias override',()=>assert.deepEqual(encode('W.Alias',9007199254740993n),{kind:'integer',value:'9007199254740993'}));
check('base type override',()=>assert.equal(decode('W.Id',{kind:'integer',value:'3'}),3));
check('central integer spelling',()=>assert.equal(decode('W.Id',{kind:'integer',value:'0003'}),3));
check('central decimal spelling',()=>assert.throws(()=>decode('W.Amount',{kind:'decimal',value:'1e2'})));
check('lossy integer rejected',()=>assert.throws(()=>encode('W.Id',9007199254740992)));
console.log(JSON.stringify({cases,elapsed_ms:performance.now()-started,peak_rss_bytes:process.platform==='linux'?process.resourceUsage().maxRSS*1024:null,memory_scope:process.platform==='linux'?'Bun self maxRSS, no child processes':'unavailable',bun_version:Bun.version}));
'''
report = {'schema_version':1,'recorded_at':datetime.now(timezone.utc).isoformat(),'scope':'CLI generation and representation conversion only; no application execution/adoption proof','environment':{'platform':platform.platform(),'architecture':platform.machine()},'steps':[],'status':'incomplete','fixture_specification':SPEC,'native_script':NATIVE,'driver_source':Path(__file__).read_text()}
try:
    report['binary_sha256']=hashlib.sha256(BINARY.read_bytes()).hexdigest()
    with tempfile.TemporaryDirectory(prefix='workflow-codec-cli-',dir=ROOT/'target') as temporary:
        base=Path(temporary);(base/'spec').mkdir();(base/'app').mkdir()
        (base/'spec/w.dctx0').write_text(SPEC)
        def call(args):
            started=time.perf_counter()
            result=subprocess.run([str(BINARY),*args],cwd=base,capture_output=True,text=True,timeout=30)
            report['steps'].append({'arguments':args,'exit_code':result.returncode,'elapsed_ms':1000*(time.perf_counter()-started),'stderr':result.stderr})
            assert result.returncode==0,(args,result.stderr)
            return json.loads(result.stdout)
        call(['check','spec','--json'])
        call(['verify','init','spec','--project','app','--target','typescript','--subject','W','--json'])
        generated=call(['verify','scaffold-codecs','spec','--project','app','--integer','bigint','--type','W.Id=number','--type','W.Alias=bigint','--enum','tagged','--option','undefined','--json'])
        assert generated['status']=='created'
        report['snapshot']=generated['snapshot'];report['configuration']=generated['configuration']
        (base/'smoke.ts').write_text(NATIVE)
        started=time.perf_counter()
        result=subprocess.run(['bun','run','smoke.ts'],cwd=base,capture_output=True,text=True,timeout=30)
        report['native']={'exit_code':result.returncode,'wall_ms':1000*(time.perf_counter()-started),'stderr':result.stderr}
        assert result.returncode==0,result.stderr
        report['native'].update(json.loads(result.stdout))
    report['status']='pass'
finally:
    (ROOT/'target/workflow-tools-native-cli.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'status':report['status'],'cases':len(report.get('native',{}).get('cases',[]))}))
